package dev.workshopvideo;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.zip.*;
/** Signed test APK, installed only on the project emulator. No production test menu or hook. */
public final class EmulatorChecks extends Instrumentation {
 private VideoApp app;private File output;private int checks;private JSONArray results=new JSONArray();
 public void onCreate(Bundle args){super.onCreate(args);start();}
 private void check(boolean ok,String name)throws Exception{if(!ok)throw new AssertionError(name);checks++;results.put(name);android.util.Log.i("EmulatorChecks","PASS "+name);}
 private <T extends View>T find(View root,Class<T> type){if(type.isInstance(root))return type.cast(root);if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){T found=find(group.getChildAt(i),type);if(found!=null)return found;}}return null;}
 private Bitmap bitmap(TextureView texture){final Bitmap[] out={null};runOnMainSync(()->{if(texture.isAvailable())out[0]=texture.getBitmap();});return out[0];}
 private void save(Bitmap image,String name)throws Exception{try(FileOutputStream out=new FileOutputStream(new File(output,name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}}
 private JSONObject effects(){JSONObject o=new JSONObject();VideoApp.put(o,"zoom",1);VideoApp.put(o,"pan",true);VideoApp.put(o,"scrollStrength",.5);return o;}
 private void job(String id,String kind,File input)throws Exception{File target=app.video(id);target.getParentFile().mkdirs();Files.copy(input.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);JSONObject record=new JSONObject().put("id",id).put("kind",kind).put("state","saved").put("storage","private").put("compatible",true).put("title","Local validation "+kind).put("effects",effects()).put("uri",app.videoUri(id).toString());app.save(record);}
 private void paging(String id,String kind,int count)throws Exception{
  WallpaperStore.prefs(app).edit().putInt("launcherPages",count).commit();Intent intent=new Intent(app,WallpaperPreviewActivity.class).putExtra("id",id).putExtra("scope",0).putExtra("fit",false).putExtra("effects",effects().toString()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity activity=startActivitySync(intent);waitForIdleSync();final TextureView[] texture={null};final SeekBar[] page={null};runOnMainSync(()->{View root=activity.findViewById(android.R.id.content);texture[0]=find(root,TextureView.class);page[0]=find(root,SeekBar.class);});check(texture[0]!=null&&page[0]!=null,kind+" preview has native TextureView and paging controls");
  try{for(int index=0;index<count;index++){final int progress=index*1000;runOnMainSync(()->page[0].setProgress(progress));Bitmap frame=null;boolean correct=false;int actual=-1;long end=SystemClock.elapsedRealtime()+90000;
    while(SystemClock.elapsedRealtime()<end){if(frame!=null)frame.recycle();frame=bitmap(texture[0]);if(frame!=null){float width=frame.getWidth(),height=frame.getHeight(),scale=Math.max(width/1440f,height/960f),visible=width/scale;float x=visible/2+(1440-visible)*index/(count-1f);int expected=Math.round(255*x/1439);actual=Color.red(frame.getPixel(frame.getWidth()/2,frame.getHeight()/2));int green=Color.green(frame.getPixel(frame.getWidth()/2,frame.getHeight()/2));if(Math.abs(expected-actual)<=12&&green>10){correct=true;break;}}Thread.sleep(400);}
    check(correct,kind+" "+count+" pages: proportional segment "+index+" red="+actual);save(frame,kind+"-"+count+"-"+index+".png");frame.recycle();}
   Bitmap screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){save(screenshot,kind+"-"+count+"-ui.png");screenshot.recycle();}
  }finally{runOnMainSync(activity::finish);waitForIdleSync();}
 }
 public void onStart(){Bundle report=new Bundle();int result=Activity.RESULT_CANCELED;try{
  if(!Build.HARDWARE.equals("ranchu")&&!Build.HARDWARE.equals("goldfish"))throw new SecurityException("Validation refuses physical devices");app=(VideoApp)getTargetContext().getApplicationContext();output=new File(app.getExternalFilesDir(null),"validation");output.mkdirs();
  check(Build.VERSION.SDK_INT>=29,"full Android runtime API "+Build.VERSION.SDK_INT+" "+Build.HARDWARE);Activity main=startActivitySync(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(!main.isFinishing(),"production MainActivity launches");long uiDeadline=SystemClock.elapsedRealtime()+30000;boolean appVisible=false;while(SystemClock.elapsedRealtime()<uiDeadline){android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null&&"dev.workshopvideo".contentEquals(root.getPackageName())){appVisible=true;break;}Thread.sleep(500);}check(appVisible,"production MainActivity is visible without a blocking system or ANR dialog");Thread.sleep(1500);Bitmap screen=getUiAutomation().takeScreenshot();if(screen!=null){save(screen,"main.png");screen.recycle();}runOnMainSync(main::finish);
  Bitmap gradient=Bitmap.createBitmap(1440,960,Bitmap.Config.ARGB_8888);int[] row=new int[1440];for(int x=0;x<1440;x++){int red=Math.round(x*255f/1439);row[x]=Color.rgb(red,255-red,64);}for(int y=0;y<960;y++)gradient.setPixels(row,0,1440,0,y,1440,1);File image=new File(app.getCacheDir(),"validation-gradient.png");try(FileOutputStream out=new FileOutputStream(image)){gradient.compress(Bitmap.CompressFormat.PNG,100,out);}gradient.recycle();
  File scene=new File(app.getCacheDir(),"validation-scene.zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(scene))){z.putNextEntry(new ZipEntry("wallpaper-mobile.json"));z.write(new JSONObject().put("format","WallpaperMobileScene/1").put("width",1440).put("height",960).put("layers",new JSONArray().put(new JSONObject().put("file","gradient.png"))).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));z.closeEntry();z.putNextEntry(new ZipEntry("gradient.png"));z.write(Files.readAllBytes(image.toPath()));z.closeEntry();}
  String imageId="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",sceneId="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",videoId="cccccccccccccccccccccccccccccccc";job(imageId,"image",image);job(sceneId,"scene",scene);
  for(int pages:new int[]{2,3,5})paging(imageId,"image",pages);for(int pages:new int[]{3,5})paging(sceneId,"scene",pages);
  File video=new File(app.getCacheDir(),"validation.mp4");try(InputStream input=getContext().getAssets().open("validation.mp4")){Files.copy(input,video.toPath(),StandardCopyOption.REPLACE_EXISTING);}job(videoId,"video",video);WallpaperRenderer.verify(app,video);check(true,"real MediaPlayer external-texture EGL video verification");paging(videoId,"video",3);
  report.putString("result","PASS");result=Activity.RESULT_OK;
 }catch(Throwable error){android.util.Log.e("EmulatorChecks","Failed",error);report.putString("result","FAIL");report.putString("error",android.util.Log.getStackTraceString(error));}finally{try{JSONObject json=new JSONObject().put("result",report.getString("result")).put("error",report.getString("error","")).put("checks",checks).put("api",Build.VERSION.SDK_INT).put("hardware",Build.HARDWARE).put("passed",results);if(output!=null)Files.write(new File(output,"results.json").toPath(),json.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));report.putInt("checks",checks);}catch(Exception ignored){}finish(result,report);}}
}
